export function bubbleSort(values: number[]) {
  const copy = [...values];

  for (let end = copy.length - 1; end > 0; end -= 1) {
    for (let index = 0; index < end; index += 1) {
      if (copy[index] > copy[index + 1]) {
        [copy[index], copy[index + 1]] = [copy[index + 1], copy[index]];
      }
    }
  }

  return copy;
}

