public static int[] bubbleSort(int[] values) {
    int[] copy = Arrays.copyOf(values, values.length);

    for (int end = copy.length - 1; end > 0; end--) {
        for (int index = 0; index < end; index++) {
            if (copy[index] > copy[index + 1]) {
                int temp = copy[index];
                copy[index] = copy[index + 1];
                copy[index + 1] = temp;
            }
        }
    }

    return copy;
}

