export function selectionSort(values: number[]) {
  const copy = [...values];

  for (let start = 0; start < copy.length; start += 1) {
    let minIndex = start;

    for (let index = start + 1; index < copy.length; index += 1) {
      if (copy[index] < copy[minIndex]) {
        minIndex = index;
      }
    }

    [copy[start], copy[minIndex]] = [copy[minIndex], copy[start]];
  }

  return copy;
}

