export function insertionSort(values: number[]) {
  const copy = [...values];

  for (let i = 1; i < copy.length; i++) {
    const key = copy[i];
    let j = i - 1;

    while (j >= 0 && copy[j] > key) {
      copy[j + 1] = copy[j];
      j -= 1;
    }
    copy[j + 1] = key;
  }

  return copy;
}

